<?php
require_once 'sacco_common.php';
$month=$_GET['month']??date('Y-m');if(!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$month))$month=date('Y-m');
$start=$month.'-01';$end=(new DateTime($start))->modify('first day of next month')->format('Y-m-d');$sid=(int)($_GET['sacco_id']??0);
$saccos=$conn->query("SELECT sacco_id,sacco_name FROM hr_saccos ORDER BY sacco_name")->fetch_all(MYSQLI_ASSOC);
$sql="SELECT s.sacco_id,s.sacco_name,COALESCE(SUM(CASE WHEN t.transaction_type='contribution' THEN t.amount ELSE 0 END),0) contributions,COALESCE(SUM(CASE WHEN t.transaction_type='withdrawal' THEN t.amount ELSE 0 END),0) withdrawals,COUNT(DISTINCT CASE WHEN t.transaction_type='contribution' THEN m.sacco_member_id END) contributing_members FROM hr_saccos s LEFT JOIN hr_sacco_members m ON m.sacco_id=s.sacco_id LEFT JOIN hr_sacco_transactions t ON t.sacco_member_id=m.sacco_member_id AND t.transaction_date>=? AND t.transaction_date<?".($sid?' WHERE s.sacco_id=?':'')." GROUP BY s.sacco_id,s.sacco_name ORDER BY s.sacco_name";
$st=$conn->prepare($sql);if($sid)$st->bind_param('ssi',$start,$end,$sid);else $st->bind_param('ss',$start,$end);$st->execute();$summary=$st->get_result();
$sql2="SELECT m.sacco_member_id,m.sacco_account_no,s.sacco_name,COALESCE(NULLIF(TRIM(CONCAT(e.first_name,' ',e.last_name)),''),u.email,CONCAT('User #',u.user_id)) full_name,COALESCE(SUM(CASE WHEN t.transaction_type='contribution' THEN t.amount ELSE 0 END),0) contributions,COALESCE(SUM(CASE WHEN t.transaction_type='withdrawal' THEN t.amount ELSE 0 END),0) withdrawals FROM hr_sacco_members m JOIN hr_saccos s ON s.sacco_id=m.sacco_id JOIN users u ON u.user_id=m.user_id LEFT JOIN employees e ON e.employee_id=u.employee_id LEFT JOIN hr_sacco_transactions t ON t.sacco_member_id=m.sacco_member_id AND t.transaction_date>=? AND t.transaction_date<?".($sid?' WHERE m.sacco_id=?':'')." GROUP BY m.sacco_member_id,m.sacco_account_no,s.sacco_name,full_name ORDER BY s.sacco_name,full_name";
$st2=$conn->prepare($sql2);if($sid)$st2->bind_param('ssi',$start,$end,$sid);else $st2->bind_param('ss',$start,$end);$st2->execute();$detail=$st2->get_result();
$rows=[];$tc=0;$tw=0;while($r=$summary->fetch_assoc()){$r['contributions']=(float)$r['contributions'];$r['withdrawals']=(float)$r['withdrawals'];$tc+=$r['contributions'];$tw+=$r['withdrawals'];$rows[]=$r;}
require_once 'navbar.php';
?>
<main class="ml-64 p-6 max-w-7xl mx-auto"><div class="flex justify-between flex-wrap gap-3 mb-6"><div><h1 class="text-2xl font-bold"><i class="fa-solid fa-chart-line text-blue-600 mr-2"></i>SACCO Reports</h1><p class="text-sm text-gray-500">Monthly and organisation-wide contribution summaries.</p></div><button onclick="window.print()" class="bg-gray-800 text-white px-4 py-2 rounded">Print Report</button></div>
<form method="get" class="bg-white border rounded-xl p-4 mb-5 flex flex-wrap items-end gap-3"><label class="text-sm">Month<input type="month" name="month" value="<?=se($month)?>" class="block border rounded p-2"></label><label class="text-sm">SACCO<select name="sacco_id" class="block border rounded p-2"><option value="0">All SACCOs</option><?php foreach($saccos as $s):?><option value="<?=$s['sacco_id']?>" <?=$sid===$s['sacco_id']?'selected':''?>><?=se($s['sacco_name'])?></option><?php endforeach;?></select></label><button class="bg-blue-600 text-white rounded px-5 py-2">Generate</button></form>
<div class="grid sm:grid-cols-3 gap-4 mb-5"><div class="bg-white border rounded-xl p-4">Contributions<b class="block text-2xl text-green-700">KSh <?=sm($tc)?></b></div><div class="bg-white border rounded-xl p-4">Withdrawals<b class="block text-2xl text-orange-600">KSh <?=sm($tw)?></b></div><div class="bg-white border rounded-xl p-4">Net movement<b class="block text-2xl text-blue-700">KSh <?=sm($tc-$tw)?></b></div></div>
<section class="bg-white border rounded-xl overflow-x-auto mb-6"><h2 class="font-bold p-4 border-b">SACCO Summary — <?=se(date('F Y',strtotime($start)))?></h2><table class="w-full text-sm"><thead class="bg-gray-100"><tr><th class="p-3 text-left">SACCO</th><th class="p-3 text-center">Contributing members</th><th class="p-3 text-right">Contributions</th><th class="p-3 text-right">Withdrawals</th><th class="p-3 text-right">Net</th></tr></thead><tbody><?php if($rows):foreach($rows as $r):?><tr class="border-t"><td class="p-3 font-semibold"><?=se($r['sacco_name'])?></td><td class="p-3 text-center"><?=$r['contributing_members']?></td><td class="p-3 text-right"><?=sm($r['contributions'])?></td><td class="p-3 text-right"><?=sm($r['withdrawals'])?></td><td class="p-3 text-right font-semibold"><?=sm($r['contributions']-$r['withdrawals'])?></td></tr><?php endforeach;?><?php else:?><tr><td colspan="5" class="p-6 text-center">No records.</td></tr><?php endif;?></tbody></table></section>
<section class="bg-white border rounded-xl overflow-x-auto"><h2 class="font-bold p-4 border-b">Employee Details</h2><table class="w-full text-sm"><thead class="bg-gray-100"><tr><th class="p-3 text-left">Employee</th><th class="p-3 text-left">SACCO</th><th class="p-3 text-left">Account</th><th class="p-3 text-right">Contributions</th><th class="p-3 text-right">Withdrawals</th><th class="p-3 text-right">Net</th><th class="p-3">Statement</th></tr></thead><tbody><?php if($detail->num_rows):while($r=$detail->fetch_assoc()):?><tr class="border-t"><td class="p-3"><?=se($r['full_name'])?></td><td class="p-3"><?=se($r['sacco_name'])?></td><td class="p-3"><?=se($r['sacco_account_no']?:'—')?></td><td class="p-3 text-right"><?=sm($r['contributions'])?></td><td class="p-3 text-right"><?=sm($r['withdrawals'])?></td><td class="p-3 text-right"><?=sm($r['contributions']-$r['withdrawals'])?></td><td class="p-3 text-center"><a class="text-blue-600 underline" href="sacco_member_statement.php?id=<?=$r['sacco_member_id']?>">Open</a></td></tr><?php endwhile;?><?php else:?><tr><td colspan="7" class="p-6 text-center">No member transactions in this month.</td></tr><?php endif;?></tbody></table></section></main>
<style>@media print{.hr-sidebar,.hr-mobile-toggle,.hr-sidebar-overlay,form,button{display:none!important}main{margin:0!important;padding:10px!important;max-width:none!important}}</style>
